import SilkCursorTrail from '@/components/mfa/SilkCursorTrail'

// Once, e.g. in your root layout: it covers the viewport and never blocks clicks.
export default function Layout({children}: {children: React.ReactNode}) {
  return (
    <>
      {children}
      <SilkCursorTrail headColor="#ff8a3d" tailColor="#ff3d81" />
    </>
  )
}
